package main

import (
	"fmt"
	"strings"
)

func perimeter(w, h int) int {
	return 2 * (w + h)
}

func shout(word string) {
	fmt.Println(strings.ToUpper(word) + "!")
}

func drain(level int) {
	level = 0
}

func main() {
	fuel := 40
	fmt.Printf("Perimeter: %d\n", perimeter(5, 2))
	shout("go")
	drain(fuel)
	fmt.Printf("Fuel: %d\n", fuel)
}

