package main

import "fmt"

func minMax(nums []int) (int, int) {
	lo, hi := nums[0], nums[0]
	for _, n := range nums {
		if n < lo {
			lo = n
		}
		if n > hi {
			hi = n
		}
	}
	return lo, hi
}

func divmod(a, b int) (int, int) {
	return a / b, a % b
}

func scale(nums []int, k int) {
	for i := range nums {
		nums[i] *= k
	}
}

func main() {
	lo, hi := minMax([]int{17, 3, 42, 8})
	fmt.Printf("Min: %d, Max: %d\n", lo, hi)
	_, rem := divmod(17, 5)
	fmt.Printf("Remainder: %d\n", rem)
	s := []int{1, 2, 3}
	scale(s, 10)
	fmt.Println(s)
}

