package main

import (
	"fmt"
	"strings"
)

func sumAndAverage(nums []float64) (float64, float64) {
	sum := 0.0
	for _, n := range nums {
		sum += n
	}
	return sum, sum / float64(len(nums))
}

func firstAndLast(words []string) (string, string) {
	return words[0], words[len(words)-1]
}

func shoutAll(words []string) {
	for i := range words {
		words[i] = strings.ToUpper(words[i])
	}
}

func main() {
	prices := []float64{2.5, 4.25, 3.75}
	words := []string{"ready", "set", "go"}
	sum, avg := sumAndAverage(prices)
	fmt.Printf("Sum: %.2f, Average: %.2f\n", sum, avg)
	_, last := firstAndLast(words)
	fmt.Printf("Last: %s\n", last)
	shoutAll(words)
	fmt.Println(words)
}

steps.body:
You can name the results in the signature. Named results are local variables that start at their zero values, and a bare `return` returns whatever they hold at that moment.

```go
func mean(nums []int) (avg float64, ok bool) {
	if len(nums) == 0 {
		return // 0, false
	}
	// ...
}
```

The names also document what each result means. Use bare returns only in short functions, because in a long one the reader has to hunt for the values. You can still write `return avg, true` explicitly.

A **guard clause** is an early `return` at the top that rejects input the rest of the function cannot handle. Without one, `nums[0]` of an empty slice panics with index out of range, and an `int` divided by a zero length panics too. Float division does not panic: `float64(sum) / float64(len(nums))` with both at zero quietly gives NaN. Returning `ok` as `false` tells the caller the result means nothing.

Assign named results with `=`. Inside an `if` or a loop, `:=` would create a new variable that shadows the result, so the result itself never changes.

example.code:
package main

import "fmt"

func mean(nums []int) (avg float64, ok bool) {
	if len(nums) == 0 {
		return // avg is 0, ok is false
	}
	sum := 0
	for _, n := range nums {
		sum += n
	}
	avg = float64(sum) / float64(len(nums))
	ok = true
	return
}

func main() {
	avg, ok := mean([]int{4, 8, 6})
	fmt.Printf("%.2f %t\n", avg, ok)
	avg, ok = mean([]int{})
	fmt.Printf("%.2f %t\n", avg, ok)
}

