package main

import "fmt"

func bounds(nums []int) (lo, hi int, ok bool) {
	if len(nums) == 0 {
		return
	}
	lo, hi = nums[0], nums[0]
	for _, n := range nums {
		if n < lo {
			lo = n
		}
		if n > hi {
			hi = n
		}
	}
	ok = true
	return
}

func main() {
	lo, hi, ok := bounds([]int{7, 2, 9, 4})
	fmt.Printf("%d %d %t\n", lo, hi, ok)
	lo, hi, ok = bounds([]int{})
	fmt.Printf("%d %d %t\n", lo, hi, ok)
}
